"""JSON batch entry point for the eMicro CPU control plane.

Reads one UTF-8 JSON request from stdin, validates the whole-request envelope
and every job's structure, types and static bounds, then replays each valid
job's events through the CPU map agent and writes one JSON response to stdout.
Invalid job structure yields ``{"error":"invalid"}`` for that job with no
replay; malformed input or exceeded whole-request bounds yield one
``{"error":"invalid"}`` for the whole request.
"""
import json
import math
import re
import sys

from ebpf.helper import Agent
from syntax import parse, PolicyError

__all__ = ['solve']

# ------------------------------------------------------------- constants ---
MAX_INPUT = 24 * 1048576          # whole-request raw input budget
MAX_JOBS = 4
MAX_EVENTS = 200000               # total events over structurally valid jobs
MAX_STAGES = 16                   # total stage events over valid jobs
MAX_POLICY_BYTES = 8 * 1048576    # total UTF-8 policy bytes over valid jobs
MAX_ATOMS = 32768                 # total atom occurrences (valid policy strings)
MAX_PATHS = 65536                 # total path-service occurrences
MAX_JOB_EVENTS = 200000
MAX_NESTING = 64                  # JSON container levels, request object = 1

U32 = 4294967295
LABEL_MAX = U32 - 1

JOB_KEYS = frozenset(('services', 'limits', 'events'))
JOBS_KEY = frozenset(('jobs',))
SERVICE_KEYS = frozenset(('name', 'label'))
LIMIT_KEYS = frozenset(('images', 'cells', 'units', 'contexts',
                        'connections', 'packets', 'files'))
LIMIT_BOUNDS = {'images': 16, 'cells': 262144, 'units': 1024,
                'contexts': 32768, 'connections': 4096,
                'packets': 32768, 'files': 8192}

_NAME = re.compile(r'[A-Za-z][A-Za-z0-9]{0,23}').fullmatch

# field kinds
_POS, _NAME, _TEXT, _WIRE, _PAIR, _UNIT = range(6)

SCHEMA = {
    'stage': (('epoch', _POS), ('policy', _TEXT)),
    'commit': (('epoch', _POS),),
    'retire': (('epoch', _POS),),
    'spawn': (('unit', _UNIT), ('service', _NAME)),
    'clone': (('parent', _UNIT), ('child', _UNIT)),
    'exit': (('unit', _UNIT),),
    'begin': (('unit', _UNIT), ('rid', _POS)),
    'finish': (('unit', _UNIT), ('rid', _POS)),
    'open': (('connection', _PAIR),),
    'send': (('unit', _UNIT), ('rid', _POS), ('connection', _PAIR),
             ('stream', _POS), ('destination', _NAME)),
    'recv': (('connection', _PAIR), ('stream', _POS), ('unit', _UNIT),
             ('rid', _POS), ('wire', _WIRE)),
    'close': (('connection', _PAIR),),
    'store': (('unit', _UNIT), ('rid', _POS), ('file', _PAIR)),
    'load': (('file', _PAIR), ('unit', _UNIT), ('rid', _POS)),
    'unlink': (('file', _PAIR),),
    'inspect': (),
}
SCHEMA_KEYS = dict((op, frozenset(tuple(key for key, _ in fields) + ('op',)))
                   for op, fields in SCHEMA.items())


class _Invalid(Exception):
    """The whole request is invalid."""


# ------------------------------------------------------------ JSON ingress --
def _pairs(pairs):
    obj = dict(pairs)
    if len(obj) != len(pairs):
        raise _Invalid('duplicate JSON key')
    return obj


def _constant(token):
    raise _Invalid('nonfinite JSON constant')


def _number(token):
    value = float(token)
    if not math.isfinite(value):
        raise _Invalid('JSON number overflows binary64')
    return value


def _decode(data):
    if len(data) > MAX_INPUT:
        raise _Invalid('input exceeds 24 MiB')
    text = data.decode('utf-8')
    if text[:1] == '﻿':
        raise _Invalid('leading UTF-8 BOM')
    request = json.loads(text, object_pairs_hook=_pairs,
                         parse_constant=_constant, parse_float=_number)
    if type(request) is not dict or request.keys() != JOBS_KEY:
        raise _Invalid('top-level schema')
    jobs = request['jobs']
    if type(jobs) is not list or len(jobs) > MAX_JOBS:
        raise _Invalid('jobs envelope')
    return jobs


# ------------------------------------------------------------- job checks ---
def _bad_depth(value, level):
    """True if any container in value's subtree sits deeper than level 64.

    ``value`` must be a container positioned at ``level``; objects and arrays
    contribute one level each, strings contribute none.
    """
    if level > MAX_NESTING:
        return True
    stack = [(value, level)]
    while stack:
        node, depth = stack.pop()
        if depth > MAX_NESTING:
            return True
        deeper = depth + 1
        if type(node) is list:
            for item in node:
                kind = type(item)
                if kind is list or kind is dict:
                    if deeper > MAX_NESTING:
                        return True
                    stack.append((item, deeper))
        else:
            for item in node.values():
                kind = type(item)
                if kind is list or kind is dict:
                    if deeper > MAX_NESTING:
                        return True
                    stack.append((item, deeper))
    return False


def _validate_job(job):
    """Validate one job's structure, types and static bounds.

    Returns ``(events, stages, policy_bytes, policies)``; raises on any
    structural problem so that job is reported invalid without replay.
    """
    if type(job) is not dict or job.keys() != JOB_KEYS:
        raise _Invalid('job schema')
    services = job['services']
    if type(services) is not list or not 1 <= len(services) <= 16:
        raise _Invalid('services envelope')
    names = set()
    labels = set()
    for service in services:
        if type(service) is not dict or service.keys() != SERVICE_KEYS:
            raise _Invalid('service schema')
        name = service['name']
        label = service['label']
        if type(name) is not str or _NAME(name) is None:
            raise _Invalid('service name')
        if type(label) is not int or not 1 <= label <= LABEL_MAX:
            raise _Invalid('service label')
        if name in names or label in labels:
            raise _Invalid('service duplicate')
        names.add(name)
        labels.add(label)
    limits = job['limits']
    if type(limits) is not dict or limits.keys() != LIMIT_KEYS:
        raise _Invalid('limits schema')
    for key, bound in LIMIT_BOUNDS.items():
        value = limits[key]
        if type(value) is not int or not 1 <= value <= bound:
            raise _Invalid('limit value')
    events = job['events']
    if type(events) is not list or len(events) > MAX_JOB_EVENTS:
        raise _Invalid('events envelope')
    policies = []
    policy_bytes = 0
    stages = 0
    schema = SCHEMA
    keys_for = SCHEMA_KEYS
    for event in events:
        if type(event) is not dict:
            raise _Invalid('event schema')
        op = event.get('op')
        fields = schema.get(op) if type(op) is str else None
        if fields is None:
            raise _Invalid('operation')
        if event.keys() != keys_for[op]:
            raise _Invalid('event fields')
        for key, kind in fields:
            value = event[key]
            if kind == _POS:
                if type(value) is not int or not 1 <= value <= U32:
                    raise _Invalid('integer field')
            elif kind == _NAME:
                if type(value) is not str or _NAME(value) is None:
                    raise _Invalid('name field')
            elif kind == _UNIT:
                if type(value) is not list or len(value) != 3:
                    raise _Invalid('unit field')
                if (type(value[0]) is not int or not 0 <= value[0] <= U32
                        or type(value[1]) is not int or not 1 <= value[1] <= U32
                        or type(value[2]) is not int or not 1 <= value[2] <= U32):
                    raise _Invalid('unit field')
            elif kind == _PAIR:
                if type(value) is not list or len(value) != 2:
                    raise _Invalid('pair field')
                if (type(value[0]) is not int or not 1 <= value[0] <= U32
                        or type(value[1]) is not int or not 1 <= value[1] <= U32):
                    raise _Invalid('pair field')
            elif kind == _WIRE:
                if value is not None:
                    if type(value) is not str or len(value) > 96:
                        raise _Invalid('wire field')
            # _TEXT: any string; UTF-8 encodability checked for stage policies
        if op == 'stage':
            policy = event['policy']
            if policy.isascii():
                policy_bytes += len(policy)
            else:
                try:
                    policy_bytes += len(policy.encode('utf-8'))
                except UnicodeEncodeError:
                    raise _Invalid('policy is not UTF-8 encodable')
            policies.append(policy)
            stages += 1
    return len(events), stages, policy_bytes, policies


# ------------------------------------------------------------------ solve ---
def solve(data):
    """Whole-request pipeline: decode, validate, count, replay."""
    jobs = _decode(data)
    valid = []
    total_events = 0
    total_stages = 0
    total_bytes = 0
    policies = []
    for job in jobs:
        try:
            events, stages, policy_bytes, job_policies = _validate_job(job)
        except Exception:
            valid.append(None)
            if type(job) is list or type(job) is dict:
                if _bad_depth(job, 3):
                    return {'error': 'invalid'}
            continue
        valid.append(job)
        total_events += events
        total_stages += stages
        total_bytes += policy_bytes
        policies.extend(job_policies)
    if (total_events > MAX_EVENTS or total_stages > MAX_STAGES
            or total_bytes > MAX_POLICY_BYTES):
        return {'error': 'invalid'}
    atoms = 0
    paths = 0
    parsed = {}
    for text in policies:
        entry = parsed.get(text)
        if entry is None:
            try:
                entry = parse(text)
            except PolicyError:
                continue
            parsed[text] = entry
        atoms += entry[1]
        paths += entry[2]
    if atoms > MAX_ATOMS or paths > MAX_PATHS:
        return {'error': 'invalid'}
    results = []
    for job in valid:
        if job is None:
            results.append({'error': 'invalid'})
            continue
        agent = Agent(job['services'], job['limits'], parsed)
        handlers = Agent.HANDLERS
        outcomes = []
        append = outcomes.append
        for event in job['events']:
            append(handlers[event['op']](agent, event))
        results.append({'events': outcomes})
    return {'results': results}


def main():
    try:
        data = sys.stdin.buffer.read(MAX_INPUT + 1)
        result = solve(data)
    except Exception:
        result = {'error': 'invalid'}
    text = json.dumps(result, separators=(',', ':'))
    stream = sys.stdout.buffer
    try:
        step = 1 << 20
        if len(text) <= step:
            stream.write(text.encode('utf-8'))
        else:
            for start in range(0, len(text), step):
                stream.write(text[start:start + step].encode('utf-8'))
        stream.flush()
    except Exception:
        pass
    try:
        sys.stdout.flush()
    except Exception:
        pass


if __name__ == '__main__':
    main()
